NEXT_STEPS = "\n".join(
    [
        "We call you | In the time window you choose on the form.",
        "We listen | Configuration, budget and timing, so every suggestion fits.",
        "We show you around | A site visit or a virtual tour, whenever suits you.",
    ]
)

# The first picture under the contact details (a library lounge) is replaced by a reception lounge.
OLD_INFO_IMAGE = "page-banners/contact-m2.jpeg"
NEW_INFO_IMAGE = ("media/m1.jpeg", "Artistic impression of a welcoming reception lounge at an M3M development")


def fill_contact_page(apps, schema_editor):
    page = apps.get_model("core", "InnerPage").objects.filter(key="contact").first()
    if page is None:
        return
    if not page.next_steps:
        page.next_steps = NEXT_STEPS
    if page.info_image.name == OLD_INFO_IMAGE:
        source, alt = NEW_INFO_IMAGE
        name = f"page-banners/contact-{Path(source).name}"
        if not default_storage.exists(name):
            with open(Path(settings.BASE_DIR) / "images" / source, "rb") as image:
                name = default_storage.save(name, File(image))
        page.info_image = name
        page.info_image_alt = alt
    page.save()


